-- EVT lua patch for soccer_menu (common/script/lua/menu/soccer_menu_0.03.81.lua.bin). Graft training_ground. Generated by research/scripts/menu_assemble.py (build --out patches) from research/grafts/; do not edit by hand.
-- ===== EVT training ground panel BEGIN =====
-- Training Ground (graft.toml; docs/game/mods/training-ground.md), the match HUD (soccer_menu / soccer_battle_menu):
-- SELECT in a training match (the module's action TrainingGround.Panel, CMD_TRAININGGROUND_PANEL: pad SELECT /
-- keyboard U, content\inputs\panel.toml, polled here while the rule flag training_ground.armed is on; also the rule
-- flag training_ground.panel that scripts\training_ground.lua sets when the game asks the coach-mode button) opens the drill's settings window, the framework's VRFW_MatchPanel (lua\_all\
-- 60_match_panel.lua; its layers vrfw_mp_plate / vrfw_mp_label: the mod's content\menus\training_ground_panel.toml).
-- The rows are the script's (CMND_TRAININGGROUND_ROWS: text row ids, a stadium's map for CMND_GET_MAP_NAME, a team's
-- name); a step goes to CMND_TRAININGGROUND_STEP, a live referee / tactics knob to the match engine
-- (CMND_VRFW_RULE_ENGINE_OVERRIDE, the running match); «Equipo rival» opens the rival team picker over the window (the
-- framework's VRFW_EmblemGrid with pad input, layers training_ground_emblem / training_ground_tile_label; the pages and
-- the team names are the script's CMND_TRAININGGROUND_TEAMS / CMND_TRAININGGROUND_TEAM_NAME; L2 / R2 = series, A =
-- pick, B = back); «Aplicar cambios» restarts the drill when a restart row changed (else it only closes the window: the
-- live rows act at once); «Reiniciar» / «Salir» leave the match the retail way (CMND_VRFW_MATCH_EXIT holds the retail
-- hold-to-leave button; no game reset, no title): the friendly's way back (return = "menus") reopens the hub with the
-- game kept, which starts the drill again on a restart. The game is paused while the window is open.
-- Wrapper only (PostStepSoccerMenu, every frame of the match HUD); engine calls only from it. Nothing at chunk load.
TrainingGround_Panel = TrainingGround_Panel or {}
do
  local T = TrainingGround_Panel
  T.C = {
    LOG = 3661580131, ROWS = 2957718950, STEP = 4185472827,
    LEAVE = 1040250234, OVERRIDE = 3098579726,
    FLAG_GET = 3832352740, FLAG_SET = 4282516552,
    TEXT = 4074371074 --[[CMND_TEXT_GET]], MAP_NAME = 3763041341 --[[CMND_GET_MAP_NAME]],
    EXIT = 746783004, FADE = 609722083, PAUSE = 4196529456 --[[CMND_VRFW_GAME_PAUSE]],
    TEAMS = 863131634, SET_TEAM = 1267191604,
    TEAM_NAME = 1241768648, SIDE_NAME = 741226554 --[[CMND_GET_SOCCER_TEAM_NAME(side 0 / 1)]],
    ROW_RIVAL = 2204933160 --[[game row's rival team]],
    CHECK_INPUT = 4265778440 --[[CMND_CHECK_INPUT (controller, command)]], PANEL_KEY = 3607500915,
  }
  T.PANEL_CTRLS = {2542817619, 4254465, 3572952193,
    2040330305}
  T.ARMED_FLAG = "training_ground.armed"
  T.GRID = {cols = 6, rows = 3, px = 230, py = 236, cx = 960, cy = 560}
  T.FLAG = "training_ground.panel"
  -- the window's look: config.toml [training_ground] style, answered with the rows (nil = the framework's retail look)
  T.style = nil
  T.texts = {}
  T.pending = 0

  function T.log(...)
    pcall(funcLuaCommand, T.C.LOG, "EVT training_ground panel", ...)
  end

  T.EXIT_WAIT = 480 -- frames (8 s at 60 fps) the match may take to end after the hold starts

  -- the way out failed: the screen back, the game unpaused, the drill goes on (the window can be opened again)
  function T.exit_failed(why)
    T.log("match exit FAILED:", why, "- the drill goes on")
    pcall(funcLuaCommand, T.C.EXIT, 0)
    pcall(funcLuaCommand, T.C.PAUSE, 0)
    pcall(funcLuaCommand, T.C.FADE, 0, 0.2)
    pcall(funcLuaCommand, T.C.LEAVE, -2)
  end

  local function text(id)
    if type(id) ~= "string" or id == "" then return nil end
    local t = T.texts[id]
    if t == nil then
      local ok, s = pcall(funcLuaCommand, T.C.TEXT, CRC32(id))
      t = (ok and type(s) == "string" and s ~= "") and s or id
      T.texts[id] = t
    end
    return t
  end

  -- a team's name in the game's language (the script: team_config name text), nil = unknown
  local function team_name(id)
    if type(id) ~= "number" or id == 0 then return nil end
    local ok, s = pcall(funcLuaCommand, T.C.TEAM_NAME, id)
    if ok and type(s) == "string" and s ~= "" then return s end
    return nil
  end

  -- a side's name in the running match (the retail HUD's own call: 0 user, 1 rival)
  local function side_name(side)
    local ok, good, s = pcall(funcLuaCommand, T.C.SIDE_NAME, side)
    if ok and good and type(s) == "string" and s ~= "" then return s end
    return nil
  end

  -- the format row's own rival team (the picker's «0»)
  local function row_rival(game, diff)
    if type(game) ~= "number" or game == 0 then return 0 end
    local ok, good, team = pcall(funcLuaCommand, T.C.ROW_RIVAL, game, (type(diff) == "number" and diff ~= 0) and diff or 1)
    if ok and good == true and type(team) == "number" then return team end
    return 0
  end

  local function map_name(map, code)
    if type(map) == "number" and map ~= 0 then
      local ok, s = pcall(funcLuaCommand, T.C.MAP_NAME, map)
      if ok and type(s) == "string" and s ~= "" then return s end
    end
    return code
  end

  -- the script's rows as the panel draws them; T.keys[i] = the row's key
  local function rows()
    local ok, list = pcall(funcLuaCommand, T.C.ROWS)
    local out = {}
    T.keys, T.kinds = {}, {}
    if not ok or type(list) ~= "table" then return out end
    if type(list.style) == "table" then T.style = list.style end
    T.pending = tonumber(list.pending) or 0
    for i, r in ipairs(list) do
      local v
      if r.kind == "stadium" then
        v = map_name(r.map, r.text)
      elseif r.kind == "team" then
        -- the chosen team; else the format row's own (its name, or the rival of the running match); never a raw id
        v = (type(r.text) == "string" and r.text ~= "") and r.text or nil
        if v == nil then
          local id = (type(r.team) == "number" and r.team ~= 0) and r.team or row_rival(r.game, r.difficulty)
          v = team_name(id) or (r.team == 0 and side_name(1)) or text("training_ground_val_team_row")
        end
      elseif type(r.value) == "string" and r.value ~= "" then
        v = text(r.value)
      elseif type(r.text) == "string" and r.text ~= "" then
        v = r.text
      end
      if v ~= nil and r.pending == 1 then v = v .. " *" end
      out[i] = {label = text(r.label) or tostring(r.key), value = v, disabled = r.disabled == 1,
        cycle = r.kind ~= "action" and r.kind ~= "apply" and r.kind ~= "team"}
      T.keys[i], T.kinds[i] = r.key, r.kind
    end
    return out
  end

  local function leave(again)
    pcall(funcLuaCommand, T.C.LEAVE, again and 1 or 0)
    T.leaving = true
    T.log(again and "restart: leaving the match (back to the hub, then again)" or "leave: leaving the match (back to the hub)")
  end

  -- the rival team picker: one series page of teams as emblem tiles over the window (which stays open, hidden)
  local function picker_page(series)
    local ok, page = pcall(funcLuaCommand, T.C.TEAMS, series or 0)
    if not ok or type(page) ~= "table" then return nil end
    local items = {}
    for k, t in ipairs(page.items or {}) do
      items[k] = {id = t.id, name = (type(t.name) == "string" and t.name ~= "" and t.name) or team_name(t.id) or "",
        count = "", emblem = t.emblem or 0}
    end
    page.list = items
    return page
  end

  local function picker_open(series)
    local page = picker_page(series)
    if page == nil or #page.list == 0 then
      T.log("picker: no teams", tostring(series))
      return
    end
    if T.grid == nil then
      local G = T.GRID
      T.grid = VRFW_EmblemGrid.New({tile = CRC32("training_ground_emblem"), label = CRC32("training_ground_tile_label"), cols = G.cols,
        rows = G.rows, px = G.px, py = G.py, cx = G.cx, cy = G.cy, input = "pad", log = T.log})
      if not T.grid.ok then
        T.log("picker: no training_ground_emblem layer in this menu")
        T.grid = nil
        return
      end
    end
    T.page = page
    local label = text(page.label) or ""
    VRFW_MatchPanel.suspend(true, string.format("%s  (%d / %d)", label, page.index or 1, page.count or 1))
    T.grid:Open(page.list, page.sel or 1)
    T.picking = true
    T.log("picker: series", page.index, #page.list, "teams")
  end

  local function picker_close()
    if T.grid ~= nil then T.grid:Close() end
    T.picking = nil
    VRFW_MatchPanel.suspend(false)
  end

  local function picker_step()
    local ev = T.grid:Step()
    if ev == nil then return end
    if ev.act == "back" then
      picker_close()
    elseif ev.act == "series" then
      T.grid:Close()
      local n = (T.page and T.page.index or 1) + (ev.dir or 1)
      picker_open(n < 1 and (T.page and T.page.count or 1) or n)
    elseif ev.act == "decide" then
      local it = T.page and T.page.list[ev.index]
      if it ~= nil then
        pcall(funcLuaCommand, T.C.SET_TEAM, it.id, T.page.index or 0)
        T.log("picker: rival team", it.id, it.name)
      end
      picker_close()
    end
  end

  local function change(i, dir)
    local key = T.keys and T.keys[i]
    if key == nil then return end
    if T.kinds[i] == "team" or T.kinds[i] == "apply" then return end   -- A only (decide)
    if T.kinds[i] == "action" then
      VRFW_MatchPanel.close("action")
      return leave(key == "restart")
    end
    local ok, done, okey, oval = pcall(funcLuaCommand, T.C.STEP, key, dir)
    if ok and done == true and type(okey) == "string" and okey ~= "" then
      local o, good, why = pcall(funcLuaCommand, T.C.OVERRIDE, okey, oval)
      T.log("live override", okey, tostring(oval), tostring(o and good), tostring(why))
    end
  end

  -- «Aplicar cambios»: a restart row changed = the drill starts again with them; else the window only closes (the live
  -- rows already act)
  local function apply()
    VRFW_MatchPanel.close("apply")
    if (T.pending or 0) > 0 then
      T.log("apply:", T.pending, "restart row(s) changed: the drill starts again")
      return leave(true)
    end
    T.log("apply: live rows only, no restart")
  end

  local function open()
    local P = VRFW_MatchPanel
    if type(P) ~= "table" or P.is_open() then return end
    rows() -- the style comes with them
    local ok = P.open({
      id = "training_ground",
      title = text("training_ground_name"),
      hint = {text("training_ground_hint_change"), text("training_ground_hint_decide"), text("training_ground_hint_close"),
        text("training_ground_hint_pending")},
      rows = rows,
      row_h = 44,
      change = change,
      decide = function(i)
        local k = T.kinds and T.kinds[i]
        if k == "team" then return picker_open(0) end
        if k == "apply" then return apply() end
        change(i, 1)
      end,
      closed = function(why) T.log("closed", why) end,
      style = T.style,
      pause = true,
    })
    T.log("open", tostring(ok))
  end

  -- the panel key went down this frame (a press, not a hold)
  local function panel_pressed()
    local down = false
    for _, ctrl in ipairs(T.PANEL_CTRLS) do
      local ok, on = pcall(funcLuaCommand, T.C.CHECK_INPUT, ctrl, T.C.PANEL_KEY)
      if ok and on == true then
        down = true
        break
      end
    end
    local press = down and not T.key_was
    T.key_was = down
    if not press then return false end
    local ok, armed = pcall(funcLuaCommand, T.C.FLAG_GET, T.ARMED_FLAG)
    if not (ok and type(armed) == "number" and armed ~= 0) then return false end
    T.log("panel key pressed")
    return true
  end

  function T.tick()
    if T.leaving then
      -- after the window closed: black, then the retail way out of the match (no game reset). VRFW_MATCH.exit pauses
      -- the game first: the retail hold-to-leave counts only while paused
      T.leaving = nil
      pcall(funcLuaCommand, T.C.FADE, 1, 0.2)
      local ok, why
      if type(VRFW_MATCH) == "table" and type(VRFW_MATCH.exit) == "function" then
        ok, why = VRFW_MATCH.exit()
      else
        pcall(funcLuaCommand, T.C.PAUSE, 1)
        local okc, done, w = pcall(funcLuaCommand, T.C.EXIT)
        ok, why = okc and done == true, w
      end
      T.log("match exit", tostring(ok), tostring(why))
      if ok then
        T.exit_wait = 0
      else
        T.exit_failed("refused " .. tostring(why))
      end
      return
    end
    if T.exit_wait ~= nil then
      -- the match ends within the hold (≈ 1 s of a 4 s hold): still here after EXIT_WAIT frames = the exit did not take;
      -- the drill goes on visibly instead of a black screen
      T.exit_wait = T.exit_wait + 1
      if T.exit_wait == 60 then T.log("match exit: waiting for the match to end") end
      if T.exit_wait >= T.EXIT_WAIT then
        T.exit_wait = nil
        T.exit_failed("the match did not end after " .. T.EXIT_WAIT .. " frames")
      end
      return
    end
    local P = VRFW_MatchPanel
    if type(P) ~= "table" then return end
    if P.is_open() then
      T.key_was = true -- the key that closes the window must be released before it opens it again
      if T.picking and T.grid ~= nil then
        picker_step()
      else
        P.step()
      end
      return
    end
    if not T.hidden then
      T.hidden = true
      pcall(P.hide)
    end
    local ok, v = pcall(funcLuaCommand, T.C.FLAG_GET, T.FLAG)
    local flagged = ok and type(v) == "number" and v ~= 0
    if flagged then pcall(funcLuaCommand, T.C.FLAG_SET, T.FLAG, 0) end
    if panel_pressed() or flagged then
      open()
    end
  end

  if type(PostStepSoccerMenu) == "function" then
    local prev = PostStepSoccerMenu
    function PostStepSoccerMenu(...)
      local r = table.pack(prev(...))
      local ok, err = pcall(T.tick)
      if not ok then T.log("error", tostring(err)) end
      return table.unpack(r, 1, r.n)
    end
  end
end
-- ===== EVT training ground panel END =====
